WITH base AS (SELECT id, order_id, shipped_date, cost, status, LAST_DAY(delivered_date) AS delivered_date_month_end, COALESCE(carrier, 'OTHER') AS resolved_carrier FROM shipments WHERE carrier IS DISTINCT FROM 'Flash' AND status <> 'RETURNED') SELECT a.id, a.order_id, a.shipped_date, a.cost, a.status, a.resolved_carrier, d.amount, d.channel FROM base a LEFT JOIN orders d ON a.order_id <=> d.id
